21	import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;
22	
23	/**
24	 * 现场观测离线合并 API 的主流程、失败分支与幂等边界测试（真实 H2 内存库，MySQL 兼容模式）。
25	 */
26	@SpringBootTest
27	@AutoConfigureMockMvc
28	class ObservationApiTest {
29	
30	    @Autowired
31	    private MockMvc mockMvc;
32	
33	    @Autowired
34	    private ObjectMapper objectMapper;
35	
36	    @Autowired
37	    private JdbcTemplate jdbcTemplate;
38	
39	    @BeforeEach
40	    void cleanDatabase() {
41	        jdbcTemplate.update("DELETE FROM request_log");
42	        jdbcTemplate.update("DELETE FROM observation_version");
43	        jdbcTemplate.update("DELETE FROM observation_current");
44	    }
45	
46	    private ResultActions create(String requestId, String observationId,
47	                                 String location, String reading, String note) throws Exception {
48	        Map<String, Object> body = new LinkedHashMap<>();
49	        body.put("requestId", requestId);
50	        body.put("observationId", observationId);
51	        body.put("location", location);
52	        body.put("reading", reading);
53	        body.put("note", note);
54	        return mockMvc.perform(post("/api/observations")
55	                .contentType(MediaType.APPLICATION_JSON)
56	                .content(objectMapper.writeValueAsString(body)));
57	    }
58	
59	    private ResultActions merge(String requestId, String observationId, int baseVersion,
60	                                String location, String reading, String note) throws Exception {
61	        Map<String, Object> body = new LinkedHashMap<>();
62	        body.put("requestId", requestId);
63	        body.put("baseVersion", baseVersion);
64	        body.put("location", location);
65	        body.put("reading", reading);
66	        body.put("note", note);
67	        return mockMvc.perform(post("/api/observations/{id}/merge", observationId)
68	                .contentType(MediaType.APPLICATION_JSON)
69	                .content(objectMapper.writeValueAsString(body)));
70	    }
71	
72	    private ResultActions delete(String requestId, String observationId, int expectedVersion) throws Exception {
73	        Map<String, Object> body = new LinkedHashMap<>();
74	        body.put("requestId", requestId);
75	        body.put("expectedVersion", expectedVersion);
76	        return mockMvc.perform(post("/api/observations/{id}/delete", observationId)
77	                .contentType(MediaType.APPLICATION_JSON)
78	                .content(objectMapper.writeValueAsString(body)));
79	    }
80	
81	    private ResultActions getCurrent(String observationId) throws Exception {
82	        return mockMvc.perform(get("/api/observations/{id}", observationId));
83	    }
84	
85	    private ResultActions getVersion(String observationId, int version) throws Exception {
86	        return mockMvc.perform(get("/api/observations/{id}/versions/{version}", observationId, version));
87	    }
88	
89	    private int versionCount(String observationId) {
90	        Integer count = jdbcTemplate.queryForObject(
91	                "SELECT COUNT(*) FROM observation_version WHERE observation_id = ?", Integer.class, observationId);
92	        return count == null ? 0 : count;
93	    }
94	
95	    // ---------- 创建 ----------
96	
97	    @Test
98	    void createReturnsVersionOne() throws Exception {
99	        create("req-c1", "obs-1", "站点A", "12.345", "首次记录")
100	                .andExpect(status().isCreated())
101	                .andExpect(jsonPath("$.observationId").value("obs-1"))
102	                .andExpect(jsonPath("$.version").value(1))
103	                .andExpect(jsonPath("$.deleted").value(false))
104	                .andExpect(jsonPath("$.location").value("站点A"))
105	                .andExpect(jsonPath("$.reading").value("12.345"))
106	                .andExpect(jsonPath("$.note").value("首次记录"));
107	
108	        getCurrent("obs-1")
109	                .andExpect(status().isOk())
110	                .andExpect(jsonPath("$.version").value(1))
111	                .andExpect(jsonPath("$.location").value("站点A"));
112	        assertThat(versionCount("obs-1")).isEqualTo(1);
113	    }
114	
115	    @Test
116	    void createDuplicateObservationIdReturns409() throws Exception {
117	        create("req-c2", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
118	        create("req-c3", "obs-1", "站点B", "2.0", "其他")
119	                .andExpect(status().isConflict());
120	        getCurrent("obs-1").andExpect(jsonPath("$.location").value("站点A"));
121	        assertThat(versionCount("obs-1")).isEqualTo(1);
122	    }
123	
124	    @Test
125	    void createWithInvalidReadingReturns400() throws Exception {
126	        create("req-c4", "obs-1", "站点A", "1.2345", "四位小数")
127	                .andExpect(status().isBadRequest());
128	        create("req-c5", "obs-1", "站点A", "abc", "非数字")
129	                .andExpect(status().isBadRequest());
130	        assertThat(versionCount("obs-1")).isZero();
131	    }
132	
133	    // ---------- 三方合并 ----------
134	
135	    @Test
136	    void mergeAcceptsCandidateWhenCurrentUnchanged() throws Exception {
137	        create("req-m1", "obs-1", "站点A", "1.0", "旧备注").andExpect(status().isCreated());
138	        merge("req-m2", "obs-1", 1, "站点B", "2.5", "新备注")
139	                .andExpect(status().isOk())
140	                .andExpect(jsonPath("$.version").value(2))
141	                .andExpect(jsonPath("$.location").value("站点B"))
142	                .andExpect(jsonPath("$.reading").value("2.5"))
143	                .andExpect(jsonPath("$.note").value("新备注"));
144	        assertThat(versionCount("obs-1")).isEqualTo(2);
145	        getVersion("obs-1", 1)
146	                .andExpect(status().isOk())
147	                .andExpect(jsonPath("$.location").value("站点A"));
148	    }
