150	    @Test
151	    void mergeKeepsCurrentWhenCandidateUnchanged() throws Exception {
152	        create("req-m3", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
153	        // 服务端前进到版本 2：地点改为站点B
154	        merge("req-m4", "obs-1", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
155	        // 离线端基于版本 1 提交：地点未改（仍为站点A），只改备注
156	        merge("req-m5", "obs-1", 1, "站点A", "1.0", "离线备注")
157	                .andExpect(status().isOk())
158	                .andExpect(jsonPath("$.version").value(3))
159	                .andExpect(jsonPath("$.location").value("站点B"))
