162	
163	    @Test
164	    void mergeAcceptsWhenBothSidesChangedToSameValue() throws Exception {
165	        create("req-m6", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
166	        merge("req-m7", "obs-1", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
167	        // 离线端也改成站点B：两边相同，接受且与当前相同，不加版本
168	        merge("req-m8", "obs-1", 1, "站点B", "1.0", "备注")
169	                .andExpect(status().isOk())
170	                .andExpect(jsonPath("$.version").value(2))
171	                .andExpect(jsonPath("$.location").value("站点B"));
172	        assertThat(versionCount("obs-1")).isEqualTo(2);
173	    }
174	
175	    @Test
176	    void mergeConflictReturns409AndWritesNothing() throws Exception {
177	        create("req-m9", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
178	        merge("req-m10", "obs-1", 1, "站点B", "1.0", "备注").andExpect(status().isOk());
179	        // 离线端基于版本 1 把地点改为站点C：与服务端的站点B冲突
180	        merge("req-m11", "obs-1", 1, "站点C", "1.0", "离线备注")
181	                .andExpect(status().isConflict())
182	                .andExpect(jsonPath("$.conflictFields[0]").value("location"))
183	                .andExpect(jsonPath("$.currentVersion").value(2));
184	        // 不写入任何部分结果：当前内容与版本不变，离线备注也未生效
185	        getCurrent("obs-1")
186	                .andExpect(jsonPath("$.version").value(2))
187	                .andExpect(jsonPath("$.location").value("站点B"))
188	                .andExpect(jsonPath("$.note").value("备注"));
189	        assertThat(versionCount("obs-1")).isEqualTo(2);
190	    }
191	
192	    @Test
193	    void mergeReadingComparedNumerically() throws Exception {
194	        create("req-m12", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
195	        // 候选读数 1.00 与基线 1.0 数值相等：视为未改，保留当前；结果与当前相同，不加版本
196	        merge("req-m13", "obs-1", 1, "站点A", "1.00", "备注")
197	                .andExpect(status().isOk())
198	                .andExpect(jsonPath("$.version").value(1))
199	                .andExpect(jsonPath("$.reading").value("1.0"));
200	        assertThat(versionCount("obs-1")).isEqualTo(1);
201	    }
202	
203	    @Test
204	    void mergeIdenticalToCurrentDoesNotAddVersion() throws Exception {
205	        create("req-m14", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
206	        // 离线端把备注改为“新备注”后又改回：候选与基线相同，合并结果等于当前
207	        merge("req-m15", "obs-1", 1, "站点A", "1.0", "备注")
208	                .andExpect(status().isOk())
209	                .andExpect(jsonPath("$.version").value(1));
210	        assertThat(versionCount("obs-1")).isEqualTo(1);
211	    }
212	
213	    @Test
214	    void mergeWithMissingBaseVersionReturns404() throws Exception {
215	        create("req-m16", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
216	        merge("req-m17", "obs-1", 9, "站点B", "2.0", "备注")
217	                .andExpect(status().isNotFound());
218	        assertThat(versionCount("obs-1")).isEqualTo(1);
219	    }
220	
221	    @Test
222	    void mergeOnMissingObservationReturns404() throws Exception {
223	        merge("req-m18", "obs-x", 1, "站点B", "2.0", "备注")
224	                .andExpect(status().isNotFound());
225	    }
226	
227	    // ---------- 删除与墓碑 ----------
228	
229	    @Test
230	    void deleteCreatesTombstoneVersion() throws Exception {
231	        create("req-d1", "obs-1", "站点A", "1.0", "备注").andExpect(status().isCreated());
232	        merge("req-d2", "obs-1", 1, "站点B", "2.0", "备注2").andExpect(status().isOk());
233	
234	        delete("req-d3", "obs-1", 2)
235	                .andExpect(status().isOk())
236	                .andExpect(jsonPath("$.version").value(3))
237	                .andExpect(jsonPath("$.deleted").value(true))
238	                .andExpect(jsonPath("$.location").doesNotExist())
239	                .andExpect(jsonPath("$.reading").doesNotExist())
240	                .andExpect(jsonPath("$.note").doesNotExist());
241	
242	        // 当前查询：墓碑只返回删除状态和版本
