package com.example.starter.observation;

import java.time.Instant;

/**
 * 设备时钟偏移记录：对应 device_clock_offset 表的一行。
 * 同一设备的记录按生效起始时刻划分半开区间 [effectiveFromUtc, 下一条生效起始时刻)。
 *
 * @param deviceId         采集设备唯一标识
 * @param effectiveFromUtc 偏移生效起始 UTC 时刻（含）
 * @param offsetSeconds    偏移秒数（-86400 至 86400）：矫正后时刻 = 设备本地时刻 + 偏移秒数
 */
public record DeviceOffsetEntry(
        String deviceId,
        Instant effectiveFromUtc,
        int offsetSeconds) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

import java.time.Instant;

/**
 * 设备时钟偏移登记/修改请求：登记按 (deviceId, effectiveFromUtc) 定位，区间重叠返回 409；
 * 修改按相同键定位既有记录，仅允许变更偏移秒数。
 *
 * @param requestId        全局唯一请求标识（幂等去重键）
 * @param effectiveFromUtc 偏移生效起始 UTC 时刻（含，ISO-8601）
 * @param offsetSeconds    偏移秒数（-86400 至 86400 整数）：矫正后时刻 = 设备本地时刻 + 偏移秒数
 */
public record OffsetChangeRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotNull Instant effectiveFromUtc,
        @NotNull @Min(-86400) @Max(86400) Integer offsetSeconds) {
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;
import java.util.List;

/**
 * 偏移登记/修改响应：返回偏移记录要点与同事务重建结果汇总。
 *
 * @param deviceId           采集设备唯一标识
 * @param effectiveFromUtc   偏移生效起始 UTC 时刻
 * @param offsetSeconds      变更后的偏移秒数
 * @param rebuiltSubmissions 本次重建中矫正后时刻发生变化的观测提交数
 * @param reorders           本次重建产生的不可变重排记录（胜出内容未变化时为空）
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record OffsetChangeResponse(
        String deviceId,
        Instant effectiveFromUtc,
        int offsetSeconds,
        int rebuiltSubmissions,
        List<ObservationReorder> reorders) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

import java.time.LocalDateTime;

/**
 * 设备观测提交请求：携带设备标识与设备本地时刻，服务端按命中的偏移记录换算矫正后时刻。
 *
 * @param requestId     全局唯一请求标识（幂等去重键）
 * @param submissionId  观测提交唯一标识（观测标识）
 * @param deviceId      采集设备唯一标识
 * @param deviceLocalAt 设备本地时刻（无时区，ISO-8601，如 2026-09-25T10:00:00）
 * @param location      观测地点候选值
 * @param reading       观测读数候选值，十进制字符串，最多三位小数
 * @param note          观测备注候选值
 */
public record DeviceSubmissionRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 64) String submissionId,
        @NotBlank @Size(max = 64) String deviceId,
        @NotNull LocalDateTime deviceLocalAt,
        @NotNull @Size(max = 512) String location,
        @NotNull @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading,
        @NotNull @Size(max = 1024) String note) {
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;
import java.time.LocalDateTime;

/**
 * 设备观测提交响应：返回原始本地时刻与矫正后时刻（二者均不可由客户端改写）、
 * 本次提交是否成为当前胜出提交，以及观测记录的当前版本号。
 *
 * @param submissionId   观测提交唯一标识
 * @param observationId  目标观测记录标识
 * @param deviceId       采集设备唯一标识
 * @param deviceLocalAt  设备本地时刻（原始值）
 * @param correctedAtUtc 矫正后时刻（UTC 时标，ISO-8601）
 * @param offsetSeconds  换算时命中的偏移秒数
 * @param applied        本次提交是否成为当前胜出提交并反映到观测当前内容；
 *                       查询列表时为 null；已有人工冲突解决结论时为 false
 * @param version        观测记录当前版本号；查询列表时为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record DeviceSubmissionResponse(
        String submissionId,
        String observationId,
        String deviceId,
        LocalDateTime deviceLocalAt,
        Instant correctedAtUtc,
        int offsetSeconds,
        Boolean applied,
        Integer version) {

    /**
     * 由提交记录构造查询响应（不含胜出与版本信息）。
     */
    public static DeviceSubmissionResponse of(DeviceSubmission submission) {
        return new DeviceSubmissionResponse(submission.submissionId(), submission.observationId(),
                submission.deviceId(), submission.deviceLocalAt(), submission.correctedAtUtc(),
                submission.offsetSeconds(), null, null);
    }
}

